// Exact NGP order-10 projection for the odd-perfect (20,0), W=127 branch.
// Input is the exact order-10 profile set generated by
// oddperfect_h20_w127_h10_profiles.cpp.  For each ordinary mod-10 profile,
// enumerate every compatible alternating five-block fold and match the
// negaperiodic Golay signature
//
//   gamma gamma* + eta eta* = 100   in Z[x]/(x^10+1).
//
// Build: g++ -O3 -march=native -fopenmp oddperfect_h20_w127_ngp10.cpp -o ngp10
// Run:   OMP_NUM_THREADS=5 ./ngp10 [prefix]
#include <algorithm>
#include <array>
#include <atomic>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iostream>
#include <mutex>
#include <string>
#include <unordered_map>
#include <vector>
#ifdef _OPENMP
#include <omp.h>
#else
static double omp_get_wtime(){return 0.0;}
#endif

static std::vector<int> topts(int s){
 std::vector<int>v;for(int p:{-3,-1,1,3})for(int q:{-2,0,2})if(p+q==s)v.push_back(p-q);
 std::sort(v.begin(),v.end());v.erase(std::unique(v.begin(),v.end()),v.end());return v;
}
static std::array<int,10> decode(uint64_t c){std::array<int,10>s{};for(int i=0;i<10;i++){s[i]=-5+2*(c%6);c/=6;}return s;}
static uint64_t encsig(int norm,const int n[4]){uint64_t z=norm;for(int i=0;i<4;i++)z=z*513+(n[i]+256);return z;}
static void sig_of(const std::array<int,10>&g,int&norm,int n[4]){
 norm=0;for(int x:g)norm+=x*x;
 for(int k=1;k<=4;k++){int v=0;for(int i=0;i<10-k;i++)v+=g[i]*g[i+k];for(int i=10-k;i<10;i++)v-=g[i]*g[i+k-10];n[k-1]=v;}
}
static std::vector<uint64_t> signatures(uint64_t code){
 auto s=decode(code);std::array<std::vector<int>,10>o;long long comb=1;
 for(int i=0;i<10;i++){o[i]=topts(s[i]);comb*=o[i].size();}
 std::vector<uint64_t>out;out.reserve(std::min<long long>(comb,10000));std::array<int,10>g{};
 std::function<void(int,int)>dfs=[&](int p,int norm){
  if(norm>90)return;
  if(p==10){int n[4],nn;sig_of(g,nn,n);out.push_back(encsig(nn,n));return;}
  for(int x:o[p]){g[p]=x;dfs(p+1,norm+x*x);}
 };
 dfs(0,0);std::sort(out.begin(),out.end());out.erase(std::unique(out.begin(),out.end()),out.end());return out;
}
static uint64_t complement_sig(uint64_t z){
 int n[4];for(int i=3;i>=0;i--){int d=z%513;z/=513;n[i]=d-256;}int norm=z;int m[4];for(int i=0;i<4;i++)m[i]=-n[i];return encsig(100-norm,m);
}
int main(int argc,char**argv){
 std::string pre=argc>1?argv[1]:"h10";std::vector<uint64_t>Ac,Bc,Pc;uint64_t x;
 {std::ifstream f(pre+"_A_codes.txt");while(f>>x)Ac.push_back(x);}
 {std::ifstream f(pre+"_B_codes.txt");while(f>>x)Bc.push_back(x);}
 {std::ifstream f(pre+"_pair_codes.txt");while(f>>x)Pc.push_back(x);}
 std::sort(Ac.begin(),Ac.end());std::sort(Bc.begin(),Bc.end());
 std::unordered_map<uint64_t,int>ai,bi;for(int i=0;i<(int)Ac.size();i++)ai[Ac[i]]=i;for(int i=0;i<(int)Bc.size();i++)bi[Bc[i]]=i;
 std::vector<std::vector<int>>partners(Bc.size());
 for(auto cp:Pc){uint64_t ca=cp&((1ULL<<26)-1),cb=cp>>26;auto ia=ai.find(ca),ib=bi.find(cb);if(ia==ai.end()||ib==bi.end()){std::cerr<<"decode fail\n";return 2;}partners[ib->second].push_back(ia->second);}
 for(auto&v:partners){std::sort(v.begin(),v.end());v.erase(std::unique(v.begin(),v.end()),v.end());}
 std::vector<std::vector<uint64_t>>AS(Ac.size());double t0=omp_get_wtime();
#pragma omp parallel for schedule(dynamic,1)
 for(int i=0;i<(int)Ac.size();i++)AS[i]=signatures(Ac[i]);
 long long totalAs=0;for(auto&v:AS)totalAs+=v.size();std::cerr<<"A_signatures="<<totalAs<<" generation_seconds="<<omp_get_wtime()-t0<<"\n";
 std::atomic<long long>survivingPairs{0},checkedBSigs{0};std::vector<std::pair<uint64_t,uint64_t>>surv;std::mutex mu;
#pragma omp parallel for schedule(dynamic,1)
 for(int ibx=0;ibx<(int)Bc.size();ibx++){
  if(partners[ibx].empty())continue;auto BS=signatures(Bc[ibx]);checkedBSigs+=BS.size();std::vector<char>hit(partners[ibx].size());int left=hit.size();
  for(auto sb:BS){uint64_t need=complement_sig(sb);for(int j=0;j<(int)partners[ibx].size();j++)if(!hit[j]&&std::binary_search(AS[partners[ibx][j]].begin(),AS[partners[ibx][j]].end(),need)){hit[j]=1;left--;if(!left)break;}if(!left)break;}
  if(left!=(int)hit.size()){std::lock_guard<std::mutex>g(mu);for(int j=0;j<(int)hit.size();j++)if(hit[j]){surv.push_back({Ac[partners[ibx][j]],Bc[ibx]});survivingPairs++;}}
 }
 std::cerr<<"B_signatures_checked="<<checkedBSigs<<" total_seconds="<<omp_get_wtime()-t0<<"\n";
 std::cout<<"SUMMARY input_pairs="<<Pc.size()<<" projected_NGP_survivors="<<survivingPairs<<"\n";
 std::sort(surv.begin(),surv.end());std::ofstream fo(pre+"_ngp10_survivors.txt");for(auto [a,b]:surv)fo<<a<<" "<<b<<"\n";
}
